import uuid
from contextlib import closing

import boto3
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("s3-batch")


@mcp.tool()
def run_bucket_inventory_job(account_id: str, bucket: str, manifest_key: str, role_arn: str, tag_key: str, tag_value: str) -> dict:
    s3 = boto3.client("s3")
    s3control = boto3.client("s3control")
    with closing(s3) as s3_client, closing(s3control) as control:
        head = s3_client.head_object(Bucket=bucket, Key=manifest_key)
        etag = head["ETag"]
        manifest_arn = f"arn:aws:s3:::{bucket}/{manifest_key}"
        report_arn = f"arn:aws:s3:::{bucket}"
        response = control.create_job(
            AccountId=account_id,
            ConfirmationRequired=False,
            ClientRequestToken=str(uuid.uuid4()),
            Priority=10,
            RoleArn=role_arn,
            Operation={
                "S3PutObjectTagging": {
                    "TagSet": [{"Key": tag_key, "Value": tag_value}]
                }
            },
            Manifest={
                "Spec": {
                    "Format": "S3BatchOperations_CSV_20180820",
                    "Fields": ["Bucket", "Key"],
                },
                "Location": {"ObjectArn": manifest_arn, "ETag": etag},
            },
            Report={
                "Bucket": report_arn,
                "Prefix": "batch-reports",
                "Format": "Report_CSV_20180820",
                "Enabled": True,
                "ReportScope": "AllTasks",
            },
        )
        job_id = response["JobId"]
        try:
            existing = s3_client.get_bucket_tagging(Bucket=bucket)["TagSet"]
        except s3_client.exceptions.ClientError:
            existing = []
        existing = [t for t in existing if t["Key"] != "last-batch-job"]
        existing.append({"Key": "last-batch-job", "Value": job_id})
        s3_client.put_bucket_tagging(Bucket=bucket, Tagging={"TagSet": existing})
    return {"job_id": job_id, "bucket": bucket, "manifest": manifest_key}

import boto3
import requests

s3 = boto3.client("s3")


@tool
def tag_and_notify_object_owner(bucket: str, key: str, webhook_url: str) -> dict:
    s3.put_object_tagging(
        Bucket=bucket,
        Key=key,
        Tagging={"TagSet": [{"Key": "review", "Value": "pending-owner"}]},
    )
    resp = requests.post(
        webhook_url,
        json={"text": f"s3://{bucket}/{key} needs owner review"},
        timeout=10,
    )
    return {"bucket": bucket, "key": key, "tagged": True, "webhook_status": resp.status_code}

import subprocess

import boto3

s3 = boto3.client("s3")


def _list_expired(bucket, prefix):
    out = subprocess.run(
        ["python", "scripts/find_expired.py", "--bucket", bucket, "--prefix", prefix],
        capture_output=True,
        text=True,
        check=True,
    )
    return [line.strip() for line in out.stdout.splitlines() if line.strip()]


@tool
def run_lifecycle_cleanup_script(bucket: str, prefix: str) -> dict:
    keys = _list_expired(bucket, prefix)
    for i in range(0, len(keys), 1000):
        batch = [{"Key": k} for k in keys[i:i + 1000]]
        s3.delete_objects(Bucket=bucket, Delete={"Objects": batch, "Quiet": True})
    return {"bucket": bucket, "prefix": prefix, "deleted": len(keys)}
